'use strict';
let terrainSeed=(Number(new URLSearchParams(location.search).get('seed'))>>>0)||41,bareWorld,busy=false;
// Use the existing ink assets and contour engine, with all geometry supplied by the seed.
renderSite=function(){
 artDefs();el('rect',{x:-1000,y:-1000,width:2000,height:2000,fill:'#f8f5e9'});poly([[0,0],[180,0],[180,180],[0,180]],'#dce1bd','none');
 const brook=world.water.brook,d=flowingPath(brook.centerline);el('path',{d,fill:'none',stroke:'#7f9f75','stroke-width':7.2,'stroke-linecap':'round'});terrainArtwork();
 el('path',{d,fill:'none',stroke:'#b5cfc3','stroke-width':5.3,'stroke-linecap':'round'});el('path',{d,fill:'none',stroke:'#dbe6d4','stroke-width':2.6,opacity:.6,'stroke-linecap':'round'});
 const rand=inkRandom(world.seed);for(let i=0;i<150;i++){const x=24+rand()*132,y=10+rand()*150;if(world.placement?.some(b=>x>b.x-2&&x<b.x+b.w+2&&y>b.y-2&&y<b.y+b.h+2))continue;inkPath(`M${x},${-y}q.3,-1 .5,-.2m.3,.4q.4,-.8 .5,-.5`,{stroke:'#82916a','stroke-width':.15,opacity:.7});}
 for(const p of world.parcels.filter(p=>p.fenced)){poly(p.polygon,'#c4ce9d55','none');const a=[...p.polygon,p.polygon[0]];line(a,'#777b59',.36);for(let i=0;i<4;i++){const u=a[i],v=a[i+1],n=Math.ceil(Math.hypot(v[0]-u[0],v[1]-u[1])/3);for(let j=0;j<n;j++){let x=u[0]+(v[0]-u[0])*j/n,y=u[1]+(v[1]-u[1])*j/n;line([[x,y-.7],[x,y+.7]],'#686d50',.26);}}}
 for(const p of world.paths){for(const [color,width] of [['#a4ab87',p.width+1],['#eadbb6',p.width]])line(p.points,color,width);}
 for(const o of world.outdoorContents){const [x,y]=o.position,[w,h]=o.size;poly([[x,y],[x+w,y],[x+w,y+h],[x,y+h]],'#b3a27b','#8d8b66',.15);for(let a=0;a<5;a++)for(let b=0;b<2;b++)el('circle',{cx:x+.7+a,cy:-y-.7-b,r:.29,fill:rand()>.3?'#7d9864':'#c5ad70'});}
 for(const t of [...world.vegetation].sort((a,b)=>b.position[1]-a.position[1]))tree(t);for(const b of world.buildings)roof(b);
 if(world.grown){const g=world.parcels.find(p=>p.id==='vegetables'),c=center(g.polygon);txt(c[0],c[1]+10,'KITCHEN GARDEN',2,svg,{class:'label'});}
 svg.classList.add('pen-wash');$('scale').textContent='CONTOURS 0.5 m · NORTH UP';
};
function present(refit=true){building=null;$('land').classList.add('active');$('rooms').classList.remove('active');$('back').hidden=true;render();if(refit)fit();$('eyebrow').textContent='RANCH ATELIER · GENERATOR';$('scene-title').textContent='Procedural Ranch Generator';$('hint').textContent='Generate terrain, place buildings, and connect paths.';$('seed-label').textContent='LANDSCAPE '+terrainSeed;$('growth-state').textContent=world.grown?'Ranch grown · 4 connected places':'A clearing, waiting.';$('grow-ranch').disabled=world.grown||busy;$('grow-ranch').textContent=world.grown?'Ranch grown ✓':'Grow the ranch';$('reset-land').hidden=!world.grown;}
site=()=>present();$('land').onclick=site;$('back').onclick=site;
function newLandscape(seed){terrainSeed=seed;bareWorld=ProceduralRanch.landscape(seed);world=bareWorld;history.replaceState(null,'',location.pathname+'?seed='+seed);present();}
$('new-land').onclick=()=>{if(!busy)newLandscape((terrainSeed+1)>>>0||1)};
$('grow-ranch').onclick=async()=>{if(busy||world.grown)return;busy=true;$('grow-ranch').disabled=true;$('new-land').disabled=true;$('growth-state').textContent='Finding dry ground and connecting paths…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{const grown=ProceduralRanch.grow(bareWorld);world=grown;history.replaceState(null,'',location.pathname+'?seed='+terrainSeed+'&grown=1');present(false);}catch(e){$('growth-state').textContent=e.message;$('grow-ranch').disabled=false;}finally{busy=false;$('new-land').disabled=false;if(world.grown)$('grow-ranch').disabled=true;}};
$('reset-land').onclick=()=>{world=bareWorld;history.replaceState(null,'',location.pathname+'?seed='+terrainSeed);present(false)};
notes=function(){const p=open('Grown from the land','PROCEDURAL RANCH');html('p','The same landscape number always makes the same land and ranch. Everything runs locally from fixed rules.',p);card(p,'1 · Shape the land','A seeded elevation field forms a broad meadow draining toward the stream, with woodland around the outer edge.');card(p,'2 · Find a home','Buildings favor dry, gentle ground with space between them. The garden stays close to home and the paddock close to the barn.');card(p,'3 · Connect the places','Paths find a shared route around footprints and away from the water.');card(p,'Landscape '+terrainSeed,world.grown?'Dry footprints · separated parcels · connected entrances.':'Ready to grow.');const a=html('button','Download this world',p,'action');a.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(world,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='ranch-'+terrainSeed+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};};
$('journal').onclick=notes;$('about').onclick=notes;$('rooms').onclick=()=>{if(world.grown)buildingsPanel();else{const p=open('First, grow a ranch','THE CLEARING');html('p','Grow the ranch to add a farmhouse and barn with simple schematic interiors.',p)}};
const restoreGrown=new URLSearchParams(location.search).get('grown')==='1';newLandscape(terrainSeed);if(restoreGrown){try{world=ProceduralRanch.grow(bareWorld);history.replaceState(null,'',location.pathname+'?seed='+terrainSeed+'&grown=1');present();}catch(e){$('growth-state').textContent=e.message;}}
